import java.util.Collections;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.Random;
import java.util.Set;
import java.util.HashSet;
import java.util.HashMap;
import java.util.Map;

/**
 * Represent a rectangular grid of field positions.
 * Each position is able to store a single actor, either an animal or plant.
 *
 *
 * @version 27.02.22
 */
public class Field
{
    // A random number generator for providing random locations.
    private static final Random rand = Randomizer.getRandom();
    private static final int MAX_ALTITUDE = 5;
    // The depth and width of the field.
    private int depth, width;
    // Storage for the animals, plants, weather and altitude.
    private Object[][] animalField;
    private Object[][] plantField;
    private Map<String, double[][]> weatherField;
    private int[][] altitudeField;
    private  int waterLevel;
    private static final int maxWaterLevel = 3;
    private static final int minWaterLevel = 1;

    /**
     * Represent a field of the given dimensions.
     * @param depth The depth of the field.
     * @param width The width of the field.
     */
    public Field(int depth, int width)
    {
        this.depth = depth;
        this.width = width;
        animalField = new Object[depth][width];
        plantField = new Object[depth][width];
        weatherField = createWeatherFieldMap(depth, width);
        altitudeField = new int[depth][width];
        waterLevel = 3;
    }

    /**
     * Create a Map with a key of the weather condition attribute name
     * and a value of weather attribute.
     * @param depth The depth of the field.
     * @param width The width of the field.
     * @return The weather field Map.
     */
    private Map<String, double[][]> createWeatherFieldMap(int depth, int width)
    {
        Map<String, double[][]> mapTemp = new HashMap<>();
        WeatherCond weatherTemp = WeatherCond.Sunny;
        for (String weatherAttribute : weatherTemp.getWeatherAttributesMap().keySet()) {
            mapTemp.put(weatherAttribute, new double[depth][width]);
        }
        return mapTemp;
    }

    /**
     * Empty the field.
     */
    public void clear()
    {
        for(int row = 0; row < depth; row++) {
            for(int col = 0; col < width; col++) {
                animalField[row][col] = null;
                plantField[row][col] = null;
                for (String weatherAttribute : weatherField.keySet()) {
                    weatherField.get(weatherAttribute)[row][col] = 0;
                }
                altitudeField[row][col] = MAX_ALTITUDE;
            }
        }
        generateTerrain();
    }

    /**
     * Clear the given location.
     * The type of actor is specified to clear the correct actor field.
     * @param actor The actor in the location being cleared.
     * @param location The location to clear.
     */
    public void clear(Actor actor, Location location)
    {
        if (actor instanceof Animal){
            animalField[location.getRow()][location.getCol()] = null;
        }
        else if (actor instanceof Plant){
            plantField[location.getRow()][location.getCol()] = null;
        }
    }

    /**
     * Place an actor at the given location.
     * If there is already an actor at the location it will
     * be lost.
     * @param actor The actor to be placed.
     * @param row Row coordinate of the location.
     * @param col Column coordinate of the location.
     */
    public void place(Object actor, int row, int col)
    {
        place(actor, new Location(row, col));
    }

    /**
     * Place an actor at the given location.
     * If there is already an actor at the location it will
     * be lost.
     * @param actor The actor to be placed.
     * @param location Where to place the animal.
     */
    public void place(Object actor, Location location)
    {
        if (actor instanceof Animal) {
            animalField[location.getRow()][location.getCol()] = actor;
        }
        else if (actor instanceof Plant) {
            plantField[location.getRow()][location.getCol()] = actor;
        }
    }

    /**
     * Return the actor at the given location, if any.
     * @param location Where in the field.
     * @return The actor at the given location, or null if there is none.
     */
    public Object getObjectAt(Location location)
    {
        return getObjectAt(location.getRow(), location.getCol());
    }

    /**
     * Return the actor at the given location, if any.
     * Animals are prioritised over Plants, and are returned if both
     * are present in that location.
     * @param row The desired row.
     * @param col The desired column.
     * @return The actor at the given location, or null if there is none.
     */
    public Object getObjectAt(int row, int col)
    {
        if (animalField[row][col] != null) {
            return animalField[row][col];
        }
        return plantField[row][col];
    }

    /**
     * Generate a random location that is adjacent to the
     * given location, or is the same location.
     * The returned location will be within the valid bounds
     * of the field.
     * @param location The location from which to generate an adjacency.
     * @return A valid location within the grid area.
     */
    public Location randomAdjacentLocation(Location location)
    {
        List<Location> adjacent = adjacentLocations(location);
        return adjacent.get(0);
    }

    /**
     * Get a shuffled list of the free adjacent locations.
     * @param actor The actor finding free adjacent locations.
     * @param location Get locations adjacent to this.
     * @return A list of free adjacent locations.
     */
    public List<Location> getFreeAdjacentLocations(Actor actor, Location location)
    {
        List<Location> free = new LinkedList<>();
        List<Location> adjacent = adjacentLocations(location);

        for(Location next : adjacent) {

            if (getObjectAt(next) == null|| (actor instanceof Animal && getObjectAt(next) instanceof Plant)){
                if ((actor.canMoveOnLand() && actor.canMoveOnWater()) || (isUnderWater(next.getRow(), next.getCol()) && actor.canMoveOnWater()) || (!isUnderWater(next.getRow(), next.getCol()) && actor.canMoveOnLand())){
                    free.add(next);
                }
            }
        }
        return free;
    }

    /**
     * Try to find a free location that is adjacent to the
     * given location. If there is none, return null.
     * The returned location will be within the valid bounds
     * of the field.
     * @param actor The actor finding a free adjacent location.
     * @param location The location from which to generate an adjacency.
     * @return A valid location within the grid area.
     */
    public Location freeAdjacentLocation(Actor actor, Location location)
    {
        // The available free ones.
        List<Location> free = getFreeAdjacentLocations(actor, location);
        if(free.size() > 0) {
            return free.get(0);
        }
        else {
            return null;
        }
    }

    /**
     * Return a shuffled list of locations adjacent to the given one.
     * The list will not include the location itself.
     * All locations will lie within the grid.
     * @param location The location from which to generate adjacencies.
     * @return A list of locations adjacent to that given.
     */

import java.util.Random;
import java.util.List;
import java.util.ArrayList;
import java.util.Iterator;
import java.awt.Color;
import java.util.Map;
import java.util.HashMap;
import java.util.Set;
import java.util.HashSet;

/**
 * A simple predator-prey simulator, based on a rectangular field
 * containing actors, or animals and plants.
 *
 * @version 27.02.22
 */
public class Simulator
{
    // Constants representing configuration information for the simulation.
    // The default width for the grid.
    private static final int DEFAULT_WIDTH = 250;
    // The default depth of the grid.
    private static final int DEFAULT_DEPTH = 250;
    // List of actors in the field.
    private List<Actor> actors;
    // The probabilities that actors will be created in any given grid position.
    private Map<Actor,Double> actorCreationProb; 
    // List of diseases in the simulation.
    public static final List<Disease> diseases = createDiseases();
    // The current state of the field.
    private Field field;
    // The current step of the simulation.
    private int step;
    // A graphical view of the simulation.
    private SimulatorView view;
    // The current time in the field.
    private Time time;
    // The current weather condition of the field.
    private WeatherCond weatherCond;

    /**
     * Construct a simulation field with default size.
     */
    public Simulator()
    {
        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
    }

    /**
     * Create a simulation field with the given size.
     * @param depth Depth of the field. Must be greater than zero.
     * @param width Width of the field. Must be greater than zero.
     */
    public Simulator(int depth, int width)
    {
        if(width <= 0 || depth <= 0) {
            System.out.println("The dimensions must be greater than zero.");
            System.out.println("Using default values.");
            depth = DEFAULT_DEPTH;
            width = DEFAULT_WIDTH;
        }

        actors = new ArrayList<>();
        field = new Field(depth, width);
        time = new Time(3);
        actorCreationProb = createActorCreationProb();
        weatherCond = WeatherCond.Sunny; //Sunny weather is default 

        // Create a view of the state of each location in the field.
        view = new SimulatorView(depth, width);
        view.setColor(Lemur.class, Color.RED.darker());
        view.setColor(Panther.class, Color.ORANGE);
        view.setColor(Grass.class, Color.GREEN.darker());
        view.setColor(Water_Fern.class, Color.GREEN.brighter());
        view.setColor(Alligator.class, Color.LIGHT_GRAY);
        view.setColor(Salamander.class, Color.MAGENTA);
        view.setColor(Catfish.class, Color.BLACK);


        weatherCond.setTime(time);
        // Setup a valid starting point.
        reset();
    }

    /**
     * Create a Map with a key of an Actor object, one of each subclass of Animal and Plant,
     * and a value of the creation proability.
     * @return The actor creation prbability Map.
     */
    private Map<Actor,Double> createActorCreationProb()
    {
        Map<Actor,Double> tempMap = new HashMap<>();
        Location location = new Location(0, 0);
        tempMap.put(new Grass(time, field, location),0.8);
        tempMap.put(new Water_Fern(time, field, location),0.9);
        tempMap.put(new Salamander(time, field, location),0.5);
        tempMap.put(new Catfish(time, field, location),0.7);
        tempMap.put(new Lemur(time, field, location),0.45);
        tempMap.put(new Panther(time, field, location),0.3);
        tempMap.put(new Alligator(time, field, location),0.25);


        return tempMap;
    }

    /**
     * Create a List of all the diseases in the simulation, specify which actors start with the disease and which actors can catch the disease.
     * Starting and affected actors are specified by a Map with a String key and double value, of probability to get disease for starting actors,
     * and disease severity for affected actors. Severity ranges from 0.0 to 1.0, 0.0 being completely fatal as soon as contracted, and 1.0 meaning
     * the actor is just a disease carrier.
     * @return The diseases List.
     */
    private static List<Disease> createDiseases()
    {
        List<Disease> list = new ArrayList<>();
        Disease dengue = new Disease("dengue", true, true);

        dengue.getActorsAffectedMap().put("Lemur",0.9);
        dengue.getActorsAffectedMap().put("Panther",0.6);
        dengue.getActorsAffectedMap().put("Alligator",0.6);

        dengue.getStartingActorsMap().put("Lemur",0.4);
        list.add(dengue);

        Disease river_fever = new Disease("river_fever", true, false);

        river_fever.getActorsAffectedMap().put("Water_Fern",1.0);
        river_fever.getActorsAffectedMap().put("Catfish",0.7);
        river_fever.getActorsAffectedMap().put("Salamander",0.8);

        river_fever.getStartingActorsMap().put("Water_Fern",0.4);
        list.add(river_fever);

        return list;
    }

    /**
     * Run the simulation from its current state for a reasonably long period,
     * (4000 steps).
     */
    public void runLongSimulation()
    {
        simulate(4000);
    }

    /**
     * Run the simulation from its current state for the given number of steps.
     * Stop before the given number of steps if it ceases to be viable.
     * @param numSteps The number of steps to run for.
     */
    public void simulate(int numSteps)
    {
        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
            simulateOneStep();
            delay(60);   // uncomment this to run more slowly
        }
    }

    /**
     * Run the simulation from its current state for a single step.
     * Iterate over the whole field updating the state of each actor.
     */
    public void simulateOneStep()
    {
        step++;
        time.incrementTime(); 
        weatherCond = weatherCond.nextCondition();
        // Provide space for newborn actors.

        List<Actor> newActors = new ArrayList<>();        
        // Let all actors act.
        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
            Actor actor = it.next();
            actor.act(newActors, weatherCond);
            if(! actor.isAlive()) {
                it.remove();
            }
        }

        // Add the newly born actors to the main lists.
        actors.addAll(newActors);

        view.showStatus(step, field, weatherCond, diseases);
        field.setWeatherField(weatherCond);
    }

    /**
     * Reset the simulation to a starting position.
     */
    public void reset()
    {
        step = 0;
        actors.clear();
        populate();

        // Show the starting state in the view.
        view.showStatus(step, field, weatherCond, diseases);
    }

    /**
     * Randomly populate the field with actors.
     * Actors can only populate areas they will survive in
     * i.e. actors that will not survive in water cannot be placed there.
     */
    private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                for (Actor actor : actorCreationProb.keySet()){
                    Location location = new Location(row, col);
                    if((rand.nextDouble() <= actorCreationProb.get(actor)) && ((actor.canMoveOnLand() && actor.canMoveOnWater()) || (field.isUnderWater(location.getRow(), location.getCol()) && actor.canMoveOnWater()) || (!field.isUnderWater(location.getRow(), location.getCol()) && actor.canMoveOnLand()))) {
                        Actor newActor = actor.birth(new Location(row, col));
                        actors.add(newActor);
                        break;
                    }
                }
            }
        }
    }

    /**
     * Pause for a given time.
     * @param millisec  The time to pause for, in milliseconds
     */
    private void delay(int millisec)
    {
        try {
            Thread.sleep(millisec);
        }
        catch (InterruptedException ie) {
            // wake up
        }
    }
}

import java.util.List;
import java.util.Set;

/**
 * A class representing shared characteristics of plants.
 *
 * @version 27.02.22
 */
public abstract class Plant extends Actor
{

    protected double waterLevel;
    protected double sunLightLevel;
    private static final double maxWaterLevel = 2.5;

    /**
     * Create a new plant at location in field with time as well.
     * With a set that will add any disease that it catches
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     * @param time The time in the simulation
     */
    public Plant(Time time, Field field, Location location)
    {
        super(time, field, location);
        waterLevel = 1.5;
        sunLightLevel = 1.5;
    }

    /**
     * Make this plant act - that is: make it do
     * whatever it wants/needs to do.
     * Checks weather and updates water and sunlight levels accordingly.
     * @param newPlants A list to receive newly born plants.
     * @param weather The weather condition of the simulation.
     */
    public void act(List<Actor> newPlants, WeatherCond weather)
    {
        super.act(newPlants, weather);
        if (isAlive()){
            waterLevel-=0.5;
            sunLightLevel-= 0.25;
            sunLightLevel += getField().getWeatherAttributeValueAt("brightness", getLocation());
            if (waterLevel +getField().getWeatherAttributeValueAt("dampness", getLocation()) > maxWaterLevel){
                waterLevel = maxWaterLevel;
            }
            else {
                waterLevel += getField().getWeatherAttributeValueAt("dampness", getLocation());
            }
            if (waterLevel < 0 || sunLightLevel <= 0){
                setDead();
            }
            else {
                giveBirth(newPlants);            
            }
        }
    }

    /**
     * Returns how many plants are produced during birth
     * @return The number of plants birthed
     */
    abstract public int breed();

    /**
     * Creates a new plant
     * @param location The new location of the child
     * @param Set<Disease> The diseases that the parent had is passed down
     * @return The new plant created
     */
    abstract protected Plant birth(Location loc,Set<Disease>... parentDiseases);
}

import java.util.List;
import java.util.Iterator;
import java.util.Map;
import java.util.Set;

/**
 * A class representing shared characteristics of animals.
 *
 * @version 27.02.22
 */
public abstract class Animal extends Actor
{
    protected int foodLevel;
    protected boolean female;
    protected boolean nocturnal;

    /**
     * Create a new animal at location in field with time as well.
     * With a set that will add any disease that it catches
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     * @param time The time in the simulation
     */
    public Animal(Time time, Field field, Location location)
    {
        super(time, field, location);

    }

    /**
     * Make this animal act - that is: make it do
     * whatever it wants/needs to do.
     * Checks if the time of day matches if the animal is nocturnal or not,
     * then attempts to find food and move.
     * @param newAnimals A list to receive newly born animals.
     * @param weather The weather condition of the simulation.
     */
    public void act(List<Actor> newAnimals, WeatherCond weather)
    {
        super.act(newAnimals,weather);
        incrementHunger();
        if(isAlive()&&(getTime().isDay() != nocturnal)) {
            giveBirth(newAnimals);            
            // Move towards a source of food if found.
            Location newLocation = null;
            if (getField().getWeatherAttributeValueAt("visibility", getLocation()) > 0.4){
                newLocation = findFood();
            }
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(this, getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

    /**
     * Make this animal more hungry. This could result in the animal's death.
     */
    private void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();
        }
    }

    /**
     * Checks if the animal is female and looks for a mate
     * @param newAnimals The List of new animals that have been born to add to the simulator List of actors
     */
    protected void giveBirth(List<Actor> newAnimals)
    {
        // New animals are born into adjacent locations.
        // Get a list of adjacent free locations.
        if (female&&findMate()) {
            super.giveBirth(newAnimals);
        }
    }

    /**
     * Searches for a mate to breed with.
     * Searches first for an adjacent animal of the same dynamic type,
     * then if that animal is male.
     * @return true if a mate is found.
     */
    protected boolean findMate()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()){
            Location where = it.next();
            Object actor = field.getObjectAt(where);
            if (actor instanceof Animal) {
                Animal animal = (Animal) actor;
                if (animal.getActorName().equals(getActorName())&& !animal.female){
                    giveDiseases(animal);
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Transfer diseases from the male mate to the female and vice versa.
     * @param mate The male mate that the female breeds with.
     */
    protected void giveDiseases(Animal mate)
    {
        for (Disease disease: mate.setDiseases){
            if (disease.isSpreadByBirth()){
                setDiseases.add(disease);
            }
        }
        for (Disease disease: setDiseases){
            if (disease.isSpreadByBirth()){
                mate.getActorDiseaseSet().add(disease);
            }
        }
    }

    /**
     * Look for rabbits adjacent to the current location.
     * Only the first live rabbit is eaten.
     * @return Where food was found, or null if it wasn't.
     */
    protected Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            if ((canMoveOnLand() && canMoveOnWater()) || (field.isUnderWater(where.getRow(), where.getCol()) && canMoveOnWater()) || (!field.isUnderWater(where.getRow(), where.getCol()) && canMoveOnLand())) {
                Object actor = field.getObjectAt(where);
                if (actor instanceof Actor) {
                    Actor prey = (Actor) actor;
                    for(String actorName : getPreyFoodValuesMap().keySet()) {
                        if(getPreyFoodValuesMap().containsKey(prey.getActorName()) && prey.isAlive()) {
                            for (Disease disease: prey.setDiseases){
                                if (disease.isSpreadByEating() && disease.getActorsAffectedMap().containsKey(getActorName())){
                                    setDiseases.add(disease);
                                }
                            }
                            prey.setDead();
                            if (foodLevel + getPreyFoodValuesMap().get(prey.getActorName()) < getMaxFood()) {
                                foodLevel += getPreyFoodValuesMap().get(prey.getActorName());
                            }
                            else {
                                foodLevel = getMaxFood();
                            }
                            return where;
                        }
                    }
                }
            }
        }
        return null;
    }

    /**
     * Returns how many animals are produced during birth
     * @return The number of animals birthed
     */
    abstract protected int breed();

    /**
     * Creates a new animal 
     * @param location The new location of the child
     * @param Set<Disease> The diseases that the parent had is passed down
     * @return The new animal created
     */
    abstract protected Animal birth(Location loc, Set<Disease>... parentDiseases);

    /**
     * Returns the Map of the prey of the animal and how much food they provide it
     * @return The Map of the prey of the animal and how much food they provide it
     */
    abstract protected Map<String, Integer> getPreyFoodValuesMap();

    /**
     * Returns the max food value that the animal can have
     * @return The max food value that the animal can have
     */
    abstract protected int getMaxFood();
}

import java.awt.Color;
import java.util.HashMap;

/**
 * This class collects and provides some statistical data on the state 
 * of a field. It is flexible: it will create and maintain a counter 
 * for any class of object that is found within the field.
 *
 * @version 27.02.22
 */
public class FieldStats
{
    // Counters for each type of entity (fox, rabbit, etc.) in the simulation.
    private HashMap<Class, Counter> counters;
    // Whether the counters are currently up to date.
    private boolean countsValid;
    private Time time; 

    /**
     * Construct a FieldStats object.
     */
    public FieldStats()
    {
        // Set up a collection for counters for each type of animal that
        // we might find
        counters = new HashMap<>();
        countsValid = true;
    }

    /**
     * Get details of what is in the field.
     * @return A string describing what is in the field.
     */
    public String getPopulationDetails(Field field)
    {
        StringBuffer buffer = new StringBuffer();
        if(!countsValid) {
            generateCounts(field);
        }
        for(Class key : counters.keySet()) {
            Counter info = counters.get(key);
            buffer.append(info.getName());
            buffer.append(": ");
            buffer.append(info.getCount());
            buffer.append(' ');
        }
        return buffer.toString();
    }

    /**
     * Invalidate the current set of statistics; reset all 
     * counts to zero.
     */
    public void reset()
    {
        countsValid = false;
        for(Class key : counters.keySet()) {
            Counter count = counters.get(key);
            count.reset();
        }
    }

    /**
     * Increment the count for one class of actor.
     * @param actorClass The class of actor to increment.
     */
    public void incrementCount(Class actorClass)
    {
        Counter count = counters.get(actorClass);
        if(count == null) {
            // We do not have a counter for this species yet.
            // Create one.
            count = new Counter(actorClass.getName());
            counters.put(actorClass, count);
        }
        count.increment();

    }

    /**
     * Indicate that an animal count has been completed.
     */
    public void countFinished()
    {
        countsValid = true;
    }

    /**
     * Determine whether the simulation is still viable.
     * I.e., should it continue to run.
     * @return true If there is more than one species alive.
     */
    public boolean isViable(Field field)
    {
        // How many counts are non-zero.
        int nonZero = 0;
        if(!countsValid) {
            generateCounts(field);
        }
        for(Class key : counters.keySet()) {
            Counter info = counters.get(key);
            if(info.getCount() > 0) {
                nonZero++;
            }
        }
        return nonZero > 1;
    }

    /**
     * Generate counts of the number of actors.
     * These are not kept up to date as actors
     * are placed in the field, but only when a request
     * is made for the information.
     * @param field The field to generate the stats for.
     */
    private void generateCounts(Field field)
    {
        reset();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object actor = field.getObjectAt(row, col);
                if(actor != null) {
                    incrementCount(actor.getClass());
                }

            }
        }
        countsValid = true;
    }
}

     */
    public List<Location> adjacentLocations(Location location)
    {
        assert location != null : "Null location passed to adjacentLocations";
        // The list of locations to be returned.
        List<Location> locations = new LinkedList<>();
        if(location != null) {
            int row = location.getRow();
            int col = location.getCol();
            for(int roffset = -1; roffset <= 1; roffset++) {
                int nextRow = row + roffset;
                if(nextRow >= 0 && nextRow < depth) {
                    for(int coffset = -1; coffset <= 1; coffset++) {
                        int nextCol = col + coffset;
                        // Exclude invalid locations and the original location.
                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
                            locations.add(new Location(nextRow, nextCol));
                        }
                    }
                }
            }

            // Shuffle the list. Several other methods rely on the list
            // being in a random order.
            Collections.shuffle(locations, rand);
        }
        return locations;
    }

    /**
     * Return the depth of the field.
     * @return The depth of the field.
     */
    public int getDepth()
    {
        return depth;
    }

    /**
     * Return the width of the field.
     * @return The width of the field.
     */
    public int getWidth()
    {
        return width;
    }

    /**
     * Set the values of each weather attributes field uniformly
     * distributed around a specified average.
     * @param weather The weather condition.
     */
    public void setWeatherField(WeatherCond weather) 
    {
        for (String weatherAttribute : weatherField.keySet()) {
            double avgWeather = weather.getWeatherAttributesMap().get(weatherAttribute);
            for(int row = 0; row < depth; row++) {
                for(int col = 0; col < width; col++) {
                    weatherField.get(weatherAttribute)[row][col] = avgWeather + (rand.nextDouble() - 0.5) * 2 / 5;
                }
            }
        }

        if(weather.getDampness() > 0.7 && waterLevel < maxWaterLevel){
            waterLevel += 1;
        }

        else if (waterLevel> minWaterLevel){
            if(weather.getBrightness() > 0.9 && waterLevel > minWaterLevel + 1){
                waterLevel -=2;
            }
            else {
                waterLevel -= 1;
            }
        }
    }

    /**
     * Returns the weather attribute value at a specified location.
     * @param weatherAttribute The String name of the weather attribute.
     * @param loc The location.
     * @return The weather attribute value at the specified location.
     */
    public double getWeatherAttributeValueAt(String weatherAttribute, Location loc)
    {
        return weatherField.get(weatherAttribute)[loc.getRow()][loc.getCol()];
    }

    /**
     * Returns whether or not the location with the specified row and column
     * is under water.
     * @param row The desired row.
     * @param col The desired column.
     * @return Whether or not the location is under water.
     */
    public boolean isUnderWater(int row, int col)
    {
        return altitudeField[row][col] <= waterLevel;
    }

    /**
     * Randomly generates altitude numbers in the altitude field.
     */
    public void generateTerrain()
    {
        Location centre = new Location(rand.nextInt(depth), rand.nextInt(width));
        boolean horizontal = rand.nextBoolean();
        if (horizontal) {
            for (int z = 0; z < width; z++) {
                altitudeField[centre.getRow()][z] = 0;
            }
            int stop = 0;
            int x = 0;
            while (stop < depth / 6) {
                x++;
                Location topOrLeft = new Location(centre.getRow() - x, centre.getCol() - x);
                stop += incrementAltitude(topOrLeft.getRow(), topOrLeft.getCol(), topOrLeft.getRow() + 1, topOrLeft.getCol() + 1);
                Location bottomOrRight = new Location(centre.getRow() + x, centre.getCol() + x);
                stop += incrementAltitude(bottomOrRight.getRow(), bottomOrRight.getCol(), bottomOrRight.getRow() - 1, bottomOrRight.getCol() - 1);
                for (int z = 0; z < width; z++) {
                    stop += incrementAltitude(topOrLeft.getRow(), z, topOrLeft.getRow() + 1, z);
                    stop += incrementAltitude(bottomOrRight.getRow(), z, bottomOrRight.getRow() - 1, z);
                }
            }
        }
        else {
            for (int z = 0; z < depth; z++) {
                altitudeField[z][centre.getCol()] = 0;
            }
            int stop = 0;
            int x = 0;
            while (stop < width / 9) {
                x++;
                Location topOrLeft = new Location(centre.getRow() - x, centre.getCol() - x);
                stop += incrementAltitude(topOrLeft.getRow(), topOrLeft.getCol(), topOrLeft.getRow() + 1, topOrLeft.getCol() + 1);
                Location bottomOrRight = new Location(centre.getRow() + x, centre.getCol() + x);
                stop += incrementAltitude(bottomOrRight.getRow(), bottomOrRight.getCol(), bottomOrRight.getRow() - 1, bottomOrRight.getCol() - 1);
                for (int z = 0; z < width; z++) {
                    stop += incrementAltitude(z, topOrLeft.getCol(), z, topOrLeft.getCol() + 1);
                    stop += incrementAltitude(z, bottomOrRight.getCol(), z, bottomOrRight.getCol() - 1);
                }
            }
        }
    }

    private int incrementAltitude(int row, int col, int adjRow, int adjCol)
        {
        if (row < depth && col < width && adjRow < depth && adjCol < width && row > 0 && col > 0 && adjRow > 0 && adjCol > 0) {
            int newAltitude;
            if (rand.nextInt(depth * width / 1000) == 0) {
                newAltitude = altitudeField[adjRow][adjCol] + 1;
            }
            else {
                newAltitude = altitudeField[adjRow][adjCol];
            }
            if (newAltitude >= MAX_ALTITUDE) {
                altitudeField[row][col] = MAX_ALTITUDE;
            }
            else if (newAltitude <= 0) {
                altitudeField[row][col] = 0;
            }
            else {
                altitudeField[row][col] = newAltitude;
            }
            if (altitudeField[row][col] == MAX_ALTITUDE) {
                return 1;
            }
        }
        return 0;
    }
}

