151	     * @param numSteps The number of steps to run for.
152	     */
153	    public void simulate(int numSteps)
154	    {
155	        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
156	            simulateOneStep();
157	            delay(60);   // uncomment this to run more slowly
158	        }
159	    }
