161	    /**
162	     * Run the simulation from its current state for a single step.
163	     * Iterate over the whole field updating the state of each actor.
164	     */
165	    public void simulateOneStep()
166	    {
167	        step++;
168	        time.incrementTime(); 
169	        weatherCond = weatherCond.nextCondition();
170	        // Provide space for newborn actors.
171	
172	        List<Actor> newActors = new ArrayList<>();        
173	        // Let all actors act.
174	        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
175	            Actor actor = it.next();
176	            actor.act(newActors, weatherCond);
177	            if(! actor.isAlive()) {
178	                it.remove();
179	            }
180	        }
181	
182	        // Add the newly born actors to the main lists.
183	        actors.addAll(newActors);
184	
185	        view.showStatus(step, field, weatherCond, diseases);
186	        field.setWeatherField(weatherCond);
187	    }
