202	    /**
203	     * Randomly populate the field with actors.
204	     * Actors can only populate areas they will survive in
205	     * i.e. actors that will not survive in water cannot be placed there.
206	     */
207	    private void populate()
208	    {
209	        Random rand = Randomizer.getRandom();
210	        field.clear();
211	        for(int row = 0; row < field.getDepth(); row++) {
212	            for(int col = 0; col < field.getWidth(); col++) {
213	                for (Actor actor : actorCreationProb.keySet()){
214	                    Location location = new Location(row, col);
215	                    if((rand.nextDouble() <= actorCreationProb.get(actor)) && field.canTraverse(actor, location)) {
216	                        Actor newActor = actor.birth(new Location(row, col), Collections.emptySet());
217	                        actors.add(newActor);
218	                        break;
219	                    }
220	                }
221	            }
222	        }
223	    }
