 4	/**
 5	 * A class representing shared characteristics of plants.
 6	 *
 7	 * @version 27.02.22
 8	 */
 9	public abstract class Plant extends Actor
10	{
11	
12	    protected double waterLevel;
13	    protected double sunLightLevel;
14	    private static final double maxWaterLevel = 2.5;
15	
16	    /**
17	     * Create a new plant at location in field with time as well.
18	     * With a set that will add any disease that it catches
19	     * 
20	     * @param field The field currently occupied.
21	     * @param location The location within the field.
22	     * @param time The time in the simulation
23	     */
24	    public Plant(Time time, Field field, Location location)
25	    {
26	        super(time, field, location);
27	        waterLevel = 1.5;
28	        sunLightLevel = 1.5;
29	    }
30	
31	    /**
32	     * Make this plant act - that is: make it do
33	     * whatever it wants/needs to do.
34	     * Checks weather and updates water and sunlight levels accordingly.
35	     * @param newPlants A list to receive newly born plants.
36	     * @param weather The weather condition of the simulation.
37	     */
38	    public void act(List<Actor> newPlants, WeatherCond weather)
39	    {
40	        super.act(newPlants, weather);
41	        if (isAlive()){
42	            waterLevel-=0.5;
43	            sunLightLevel-= 0.25;
44	            sunLightLevel += getField().getWeatherAttributeValueAt("brightness", getLocation());
45	            if (waterLevel +getField().getWeatherAttributeValueAt("dampness", getLocation()) > maxWaterLevel){
46	                waterLevel = maxWaterLevel;
47	            }
48	            else {
49	                waterLevel += getField().getWeatherAttributeValueAt("dampness", getLocation());
50	            }
51	            if (waterLevel < 0 || sunLightLevel <= 0){
52	                setDead();
53	            }
54	            else {
55	                giveBirth(newPlants);            
56	            }
57	        }
58	    }
59	
60	    /**
61	     * Returns how many plants are produced during birth
62	     * @return The number of plants birthed
63	     */
64	    abstract public int breed();
65	
66	    /**
67	     * Creates a new plant
68	     * @param location The new location of the child
69	     * @param Set<Disease> The diseases that the parent had is passed down
70	     * @return The new plant created
71	     */
72	    abstract protected Plant birth(Location loc, Set<Disease> parentDiseases);
73	}

